use anyhow::{ensure,Result};
use serde::{Deserialize,Serialize};use serde_json::Value;use rusqlite::{Connection,params};use std::{path::{Path,PathBuf},collections::{BTreeMap,HashSet},io::Write};use sha2::{Digest,Sha256};
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq)]
#[serde(rename_all="camelCase")]
pub struct Revision{pub version:String,pub entity_id:String,pub kind:String,pub parents:Vec<String>,pub modified_at:u64,#[serde(default)]pub deleted:bool,pub payload:Value}
#[derive(Clone)]pub struct Store{pub root:PathBuf}
pub fn now()->u64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis()as u64}
pub fn id()->String{uuid::Uuid::new_v4().to_string()}
pub fn sha(data:&[u8])->String{format!("{:x}",Sha256::digest(data))}
pub fn heads(revisions:&[Revision])->Vec<Revision>{let parents:HashSet<_>=revisions.iter().flat_map(|r|r.parents.iter()).collect();let mut result:Vec<_>=revisions.iter().filter(|r|!parents.contains(&r.version)).cloned().collect();result.sort_by(|a,b|a.version.cmp(&b.version));result}
pub fn validate_graph(all:&[Revision])->Result<()>{
    let map:BTreeMap<_,_>=all.iter().map(|r|(&r.version,r)).collect();ensure!(map.len()==all.len(),"重复版本");let mut done=HashSet::new();
    for r in all{ensure!(!r.version.is_empty()&&!r.entity_id.is_empty(),"记录缺少id");ensure!(["question","material","attempt","note","session","plan","agent","bank","paper"].contains(&r.kind.as_str()),"未知记录类型");ensure!(r.payload["id"].as_str()==Some(&r.entity_id),"记录id不匹配");let mut unique=HashSet::new();for p in &r.parents{let prior=map.get(p).ok_or_else(||anyhow::anyhow!("缺失父版本"))?;ensure!(unique.insert(p)&&prior.entity_id==r.entity_id&&prior.kind==r.kind,"父版本无效");}}
    while done.len()<all.len(){let old=done.len();for r in all{if r.parents.iter().all(|p|done.contains(p)){done.insert(r.version.clone());}}ensure!(old!=done.len(),"版本图存在循环");}Ok(())
}
impl Store{
    pub fn open(root:impl AsRef<Path>)->Result<Self>{let s=Self{root:root.as_ref().to_path_buf()};std::fs::create_dir_all(s.root.join("assets"))?;let c=s.db()?;c.execute_batch("CREATE TABLE IF NOT EXISTS revisions(version TEXT PRIMARY KEY,entityId TEXT NOT NULL,kind TEXT NOT NULL,json TEXT NOT NULL);CREATE INDEX IF NOT EXISTS entity_ids ON revisions(entityId);CREATE TABLE IF NOT EXISTS received(name TEXT PRIMARY KEY);")?;Ok(s)}
    fn db(&self)->Result<Connection>{let c=Connection::open(self.root.join("easygot-rust.db"))?;c.busy_timeout(std::time::Duration::from_secs(10))?;Ok(c)}
    pub fn revisions(&self,id:Option<&str>)->Result<Vec<Revision>>{let c=self.db()?;let mut stmt=c.prepare("SELECT json FROM revisions WHERE (?1 IS NULL OR entityId=?1) ORDER BY rowid")?;let rows=stmt.query_map(params![id],|r|r.get::<_,String>(0))?;let mut all=vec![];for row in rows{all.push(serde_json::from_str(&row?)?);}Ok(all)}
    pub fn heads(&self,id:&str)->Result<Vec<Revision>>{Ok(heads(&self.revisions(Some(id))?))}
    pub fn get(&self,id:&str)->Result<Option<Revision>>{Ok(self.heads(id)?.into_iter().next())}
    pub fn list(&self,kind:&str)->Result<Vec<Revision>>{let all=self.revisions(None)?;let mut groups:BTreeMap<String,Vec<Revision>>=BTreeMap::new();for r in all.into_iter().filter(|r|r.kind==kind){groups.entry(r.entity_id.clone()).or_default().push(r);}let mut result=vec![];for group in groups.values(){if let Some(r)=heads(group).into_iter().next().filter(|r|!r.deleted){result.push(r);}}result.sort_by(|a,b|b.modified_at.cmp(&a.modified_at));Ok(result)}
    pub fn conflicts(&self)->Result<Vec<Vec<Revision>>>{let mut groups:BTreeMap<String,Vec<Revision>>=BTreeMap::new();for r in self.revisions(None)?{groups.entry(r.entity_id.clone()).or_default().push(r);}Ok(groups.into_values().map(|g|heads(&g)).filter(|g|g.len()>1).collect())}
    pub fn save(&self,kind:&str,entity:&str,payload:Value,base:Option<&str>,deleted:bool,resolve:bool)->Result<Revision>{
        let mut c=self.db()?;let tx=c.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;
        let all={let mut stmt=tx.prepare("SELECT json FROM revisions WHERE entityId=?1")?;let rows=stmt.query_map([entity],|r|r.get::<_,String>(0))?;let mut out=vec![];for r in rows{out.push(serde_json::from_str::<Revision>(&r?)?);}out};
        let current=heads(&all);ensure!(resolve||current.len()<=1,"此记录有同步冲突，请先处理");ensure!(current.iter().all(|r|r.kind==kind),"id被其他记录类型占用");
        let parents=if resolve{current.iter().map(|r|r.version.clone()).collect()}else if let Some(base)=base{ensure!(all.iter().any(|r|r.version==base),"编辑基础版本不存在");vec![base.to_owned()]}else{current.iter().map(|r|r.version.clone()).collect()};
        let r=Revision{version:id(),entity_id:entity.into(),kind:kind.into(),parents,modified_at:now(),deleted,payload};ensure!(r.payload["id"].as_str()==Some(entity),"payload id不匹配");
        tx.execute("INSERT INTO revisions VALUES(?1,?2,?3,?4)",params![r.version,r.entity_id,r.kind,serde_json::to_string(&r)?])?;tx.commit()?;Ok(r)
    }
    /// Validate and commit related records in one transaction (no partial bank/paper imports).
    pub fn put_many(&self,writes:Vec<(String,Value)>)->Result<()> {
        let mut db=self.db()?;let tx=db.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;let mut ids=HashSet::new();
        for(kind,payload)in writes {let entity=payload["id"].as_str().ok_or_else(||anyhow::anyhow!("记录缺少id"))?.to_owned();ensure!(ids.insert(entity.clone()),"同批记录id重复");if kind=="question"{serde_json::from_value::<crate::domain::Question>(payload.clone())?.validate()?;}
            let versions={let mut stmt=tx.prepare("SELECT json FROM revisions WHERE entityId=?1")?;let rows=stmt.query_map([&entity],|r|r.get::<_,String>(0))?;let mut rows_parsed=vec![];for row in rows{rows_parsed.push(serde_json::from_str::<Revision>(&row?)?);}rows_parsed};let current=heads(&versions);ensure!(current.len()<=1,"记录有同步冲突，请先处理");ensure!(current.iter().all(|r|r.kind==kind),"记录类型冲突");
            let revision=Revision{version:id(),entity_id:entity,kind,parents:current.iter().map(|r|r.version.clone()).collect(),modified_at:now(),deleted:false,payload};tx.execute("INSERT INTO revisions VALUES(?1,?2,?3,?4)",params![revision.version,revision.entity_id,revision.kind,serde_json::to_string(&revision)?])?;
        }tx.commit()?;Ok(())
    }
    pub fn ingest(&self,incoming:&[Revision])->Result<()>{let mut c=self.db()?;let tx=c.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;let mut all={let mut stmt=tx.prepare("SELECT json FROM revisions")?;let rows=stmt.query_map([],|r|r.get::<_,String>(0))?;let mut out=BTreeMap::new();for row in rows{let r:Revision=serde_json::from_str(&row?)?;out.insert(r.version.clone(),r);}out};let mut additions=vec![];for r in incoming{if let Some(old)=all.get(&r.version){ensure!(r==old,"同版本内容不同");}else{all.insert(r.version.clone(),r.clone());additions.push(r);}}
        validate_graph(&all.into_values().collect::<Vec<_>>())?;for r in additions{if r.kind=="question"{serde_json::from_value::<crate::domain::Question>(r.payload.clone())?.validate()?;}tx.execute("INSERT INTO revisions VALUES(?1,?2,?3,?4)",params![r.version,r.entity_id,r.kind,serde_json::to_string(r)?])?;}tx.commit()?;Ok(())}
    pub fn asset(&self,data:&[u8])->Result<String>{let hash=sha(data);let target=self.asset_path(&hash)?;if !target.exists(){let tmp=self.root.join("assets").join(format!("{}.part",id()));let mut file=std::fs::File::create(&tmp)?;file.write_all(data)?;file.sync_all()?;std::fs::rename(tmp,target)?;}Ok(hash)}
    pub fn asset_path(&self,hash:&str)->Result<PathBuf>{ensure!(hash.len()==64&&hash.bytes().all(|x|x.is_ascii_hexdigit()&&!x.is_ascii_uppercase()),"非法素材hash");Ok(self.root.join("assets").join(hash))}
    pub fn received(&self,name:&str)->Result<bool>{Ok(self.db()?.query_row("SELECT COUNT(*) FROM received WHERE name=?1",[name],|r|r.get::<_,i64>(0))?>0)}
    pub fn mark_received(&self,name:&str)->Result<()>{self.db()?.execute("INSERT OR IGNORE INTO received VALUES(?1)",[name])?;Ok(())}
    pub fn wrong(&self)->Result<Vec<Value>>{let mut latest:BTreeMap<String,Revision>=BTreeMap::new();for r in self.list("attempt")?{let key=r.payload["questionId"].as_str().unwrap_or("").to_owned();if latest.get(&key).is_none_or(|old|old.modified_at<r.modified_at){latest.insert(key,r);}}Ok(latest.into_values().filter(|r|r.payload["pending"]!=true&&r.payload["score"].as_f64().unwrap_or(0.)<r.payload["maxScore"].as_f64().unwrap_or(0.)).map(|r|r.payload).collect())}
}
pub fn asset_refs(v:&Value)->HashSet<String>{let mut out=HashSet::new();match v{Value::Object(map)=>for(k,v)in map{if (k=="asset"||k=="image")&&v.as_str().is_some_and(|s|s.len()==64&&s.bytes().all(|c|c.is_ascii_hexdigit())){out.insert(v.as_str().unwrap().into());}else{out.extend(asset_refs(v));}},Value::Array(arr)=>for v in arr{out.extend(asset_refs(v));},_=>{}}out}
#[cfg(test)]mod tests{use super::*;use serde_json::json;fn r(v:&str,p:&[&str])->Revision{Revision{version:v.into(),entity_id:"n".into(),kind:"note".into(),parents:p.iter().map(|s|s.to_string()).collect(),modified_at:0,deleted:false,payload:json!({"id":"n"})}}#[test]fn concurrent_versions(){let mut a=vec![r("a",&[]),r("b",&["a"]),r("c",&["a"])];validate_graph(&a).unwrap();assert_eq!(heads(&a).len(),2);a.push(r("d",&["b","c"]));assert_eq!(heads(&a).len(),1);assert!(validate_graph(&[r("a",&["b"]),r("b",&["a"])]).is_err());}#[test]fn storage_retains_stale_edit(){let path=std::env::temp_dir().join(id());let s=Store::open(&path).unwrap();let a=s.save("note","n",json!({"id":"n","text":"a"}),None,false,false).unwrap();s.save("note","n",json!({"id":"n","text":"b"}),Some(&a.version),false,false).unwrap();s.save("note","n",json!({"id":"n","text":"c"}),Some(&a.version),false,false).unwrap();assert_eq!(s.conflicts().unwrap().len(),1);assert!(s.save("note","n",json!({"id":"n"}),None,false,false).is_err());std::fs::remove_dir_all(path).unwrap();}}
